// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Tests of the grammar module – definition text + rules text in, one analysed G = (N, T, P, S) out.

import { describe, expect, it } from 'vitest'
import { analyzeGrammar } from './analysis'

const grammar = (rules: string, def: { nonterminals?: string; terminals?: string; start?: string } = {}) =>
  analyzeGrammar({ rules, nonterminals: def.nonterminals ?? '', terminals: def.terminals ?? '', start: def.start ?? '' })

const texts = (ps: { level: string; text: string }[], level: string) => ps.filter((p) => p.level === level).map((p) => p.text)

const TEXTBOOK = `E  -> T E'
E' -> + T E' | ε
T  -> F T'
T' -> * F T' | ε
F  -> ( E ) | i
`

describe('analyzeGrammar – N, T and S are decided once', () => {
  it('never puts a declared nonterminal into T', () => {
    const g = grammar('E -> X i', { nonterminals: 'E\nX' })
    expect(g.N).toEqual(['E', 'X'])
    expect(g.T).toEqual(['i'])
    expect(g.ll?.T).toEqual(['i'])
  })

  it('uses the same S everywhere when the chosen S is not in N', () => {
    const g = grammar('E -> i', { nonterminals: 'E', terminals: 'i', start: 'X' })
    expect(g.S).toBe('E')
    expect(g.ll?.N[0]).toBe('E')
    expect(texts(g.problems.definition, 'bad')).toContain('S = X nie je v N – použije sa E')
  })

  it('defaults S to the left side of the first rule, even when N declares another symbol first', () => {
    const g = grammar('E -> F\nF -> i', { nonterminals: 'F\nE', terminals: 'i' })
    expect(g.S).toBe('E')
    expect(g.ll?.N[0]).toBe('E')
    expect(g.N).toEqual(['E', 'F'])
  })

  it('takes a valid chosen S', () => {
    const g = grammar('E -> F\nF -> i', { start: 'F' })
    expect(g.S).toBe('F')
    expect(g.ll?.N[0]).toBe('F')
  })
})

describe('analyzeGrammar – behaviour', () => {
  it('builds the LL table of the textbook grammar', () => {
    const g = grammar(TEXTBOOK)
    expect(g.N).toEqual(['E', "E'", 'T', "T'", 'F'])
    expect(g.T).toEqual(['+', '*', '(', ')', 'i'])
    expect(g.ll?.cols).toEqual(['+', '*', '(', ')', 'i', '$'])
    const cell = (A: string, a: string) => g.ll?.table.get(A)?.get(a) ?? []
    expect(cell('E', 'i')).toEqual([1])
    expect(cell("E'", '+')).toEqual([2])
    expect(cell("E'", ')')).toEqual([3])
    expect(cell("E'", '$')).toEqual([3])
    expect(cell('F', '(')).toEqual([7])
    expect(cell('F', 'i')).toEqual([8])
    expect(g.ll?.conflicts).toEqual([])
    expect(texts(g.problems.ll, 'ok')).toEqual(['Gramatika je LL(1): 8 pravidiel, 5 neterminálov, 5 terminálov'])
  })

  it('derives N and T from the rules when nothing is declared', () => {
    const g = grammar(TEXTBOOK)
    expect(g.declared).toBe(false)
    expect(texts(g.problems.definition, 'info')).toContain('N a T nie sú deklarované – odvodzujú sa z pravidiel. „Doplniť z pravidiel“ ich vypíše.')
  })

  it('reports a consistent declared definition and keeps the notes', () => {
    const g = grammar('S -> a S | ε', { nonterminals: 'S  zoznam', terminals: 'a  písmeno' })
    expect(texts(g.problems.definition, 'ok')).toEqual(['G = (N, T, P, S) je konzistentná: |N| = 1, |T| = 1, |P| = 2, S = S'])
    expect(g.notes.get('a')).toBe('písmeno')
    expect(g.notes.get('S')).toBe('zoznam')
  })

  it('lists symbols of P missing from the declarations', () => {
    const g = grammar('E -> X i\nX -> j', { nonterminals: 'E', terminals: 'i' })
    expect(g.missingN).toEqual(['X'])
    expect(g.missingT).toEqual(['j'])
    expect(texts(g.problems.definition, 'bad')).toEqual([
      'X je na ľavej strane pravidla, ale nie je v N',
      'Symbol j (pravidlo 2) nie je v N ani v T – x ∈ (N ∪ T)*',
    ])
  })

  it('reports N ∩ T and keeps such a symbol a nonterminal', () => {
    const g = grammar('E -> X\nX -> i', { nonterminals: 'E\nX', terminals: 'X\ni' })
    expect(texts(g.problems.definition, 'bad')).toContain('X je v N aj v T – musí platiť N ∩ T = ∅')
    expect(g.T).toEqual(['i'])
  })

  it('reports syntax errors of P in both checks', () => {
    const g = grammar('E i')
    expect(g.errors).toEqual(['Riadok 1: chýba „->“ (E i)'])
    expect(texts(g.problems.definition, 'bad')).toEqual(g.errors)
    expect(texts(g.problems.ll, 'bad')).toEqual(g.errors)
    expect(g.ll).toBeNull()
  })

  it('has no LL analysis without rules but still shows the declared symbols', () => {
    const g = grammar('', { nonterminals: 'E', terminals: 'i' })
    expect(g.ll).toBeNull()
    expect(g.N).toEqual(['E'])
    expect(g.T).toEqual(['i'])
    expect(texts(g.problems.ll, 'info')).toEqual(['Zatiaľ žiadne pravidlá.'])
  })

  it('reports conflicts, left recursion and unreachable nonterminals', () => {
    const g = grammar('E -> E + i | i\nU -> i')
    expect(g.ll?.conflicts).toEqual([{ A: 'E', a: 'i', rules: [1, 2] }])
    expect(texts(g.problems.ll, 'bad')).toEqual(['Konflikt [E, i]: pravidlá 1, 2', 'Ľavá rekurzia cez E'])
    expect(texts(g.problems.ll, 'warn')).toEqual(['Neterminál U je nedosiahnuteľný zo štartu E'])
  })
})
